"use strict";
import { useCallback, useMemo } from "react";
import { useChainId, useWaitForTransactionReceipt, useWriteContract } from "wagmi";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { REWARDS_DISTRIBUTOR_ABI } from "./useVeABXRebaseClaimables";
export function useClaimRebaseReward(overrideChainId) {
  const rawChainId = useChainId();
  const resolvedChainId = useMemo(() => {
    if (overrideChainId !== void 0) {
      return overrideChainId;
    }
    if (rawChainId === UniverseChainId.Mainnet || rawChainId === UniverseChainId.Sepolia) {
      return rawChainId;
    }
    return UniverseChainId.Mainnet;
  }, [overrideChainId, rawChainId]);
  const rewardDistributor = getAbstractContracts(resolvedChainId)?.rewardDistributor;
  const {
    writeContract,
    data: claimTxHash,
    isPending: isClaimWritePending
  } = useWriteContract();
  const {
    isLoading: isClaimConfirming,
    isSuccess: isClaimSuccess,
    error: claimReceiptError
  } = useWaitForTransactionReceipt({
    hash: claimTxHash
  });
  const claim = useCallback(
    async (tokenId) => {
      if (!rewardDistributor) {
        throw new Error("Rewards distributor not configured for this chain.");
      }
      await writeContract({
        address: rewardDistributor,
        abi: REWARDS_DISTRIBUTOR_ABI,
        functionName: "claim",
        args: [tokenId]
      });
    },
    [rewardDistributor, writeContract]
  );
  return {
    claim,
    isClaimWritePending,
    isClaimConfirming,
    isClaimSuccess,
    claimTxHash,
    claimReceiptError,
    rewardDistributor
  };
}
